// These exact strings were previously generated by the server, without a
// source-backed instruction. Suppress only that known advice on presentation;
// never rewrite stored results or remove a legitimately quoted instruction.
export const generatedClothingAdvice=[
  'Sjekk klær og utstyr som passer til aktiviteten og været.',
  'Check clothing and equipment appropriate for the activity and weather.'
] as const;

export function schoolPresentationActions(actions:string[],evidence:Record<string,unknown>):string[]{
  const quote=typeof evidence.quote==='string'?evidence.quote.toLowerCase():'';
  return actions.filter((action)=>!generatedClothingAdvice.some((known)=>known===action.trim())||quote.includes(action.trim().toLowerCase()));
}

// Uses fixed server strings only. Keep the SQL gate aligned with the mapper so
// removed advice cannot create an empty practical card or consume a Next page.
export const schoolHasPracticalActionsSql=`EXISTS(SELECT 1 FROM jsonb_array_elements_text(event.actions) practical(action)
  WHERE btrim(practical.action) NOT IN ('${generatedClothingAdvice.join("','")}')
    OR strpos(lower(COALESCE(event.evidence->>'quote','')),lower(btrim(practical.action)))>0)`;
